//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\// 


    auto leakyrelu = +[](Scalar& output, Scalar input, Scalar alpha) noexcept {
        output = input > 0 ? input : alpha * input;
    };

    auto linear = +[](Scalar& output, Scalar input, Scalar alpha) noexcept {
        output = input;
    };


//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\// 

    
    // model input and flattened
    constexpr int flat_size = 9216; 
    std::array<Scalar, flat_size> model_input;

    // normalize input
    for (int i = 0; i < 9216; i++) { model_input[i] = (initial_input[i] - input_min_mean[i]) / (input_norm_std[i]); } 

    if (model_input.size() != 9216) { throw std::invalid_argument("Invalid input size. Expected size: 9216"); }

    // Dense, layer 1
    static std::array<Scalar, 4> layer_1_output;
    Dense<Scalar, 4>(
        layer_1_output.data(), model_input.data(),
        weights_1.data(), biases_1.data(),
        9216, linear, 0.0);

    // BatchNormalization, layer 2
    static std::array<Scalar, 4> layer_2_output;
    BatchNormalization<Scalar, 4>(
        layer_2_output.data(), layer_1_output.data(),
        gamma_2.data(), beta_2.data(),
        mean_2.data(), variance_2.data(),
        epsilon_2);

    // Activation, layer 3
    static std::array<Scalar, 4> layer_3_output;
    for (int i = 0; i < 4; ++i) {
        leakyrelu(layer_3_output[i], layer_2_output[i], 0.3);
    }

    // Dense, layer 4
    static std::array<Scalar, 4> layer_4_output;
    Dense<Scalar, 4>(
        layer_4_output.data(), layer_3_output.data(),
        weights_4.data(), biases_4.data(),
        4, linear, 0.0);

    // BatchNormalization, layer 5
    static std::array<Scalar, 4> layer_5_output;
    BatchNormalization<Scalar, 4>(
        layer_5_output.data(), layer_4_output.data(),
        gamma_5.data(), beta_5.data(),
        mean_5.data(), variance_5.data(),
        epsilon_5);

    // Activation, layer 6
    static std::array<Scalar, 4> layer_6_output;
    for (int i = 0; i < 4; ++i) {
        leakyrelu(layer_6_output[i], layer_5_output[i], 0.3);
    }

    // Dense, layer 7
    static std::array<Scalar, 4> layer_7_output;
    Dense<Scalar, 4>(
        layer_7_output.data(), layer_6_output.data(),
        weights_7.data(), biases_7.data(),
        4, linear, 0.0);

    // BatchNormalization, layer 8
    static std::array<Scalar, 4> layer_8_output;
    BatchNormalization<Scalar, 4>(
        layer_8_output.data(), layer_7_output.data(),
        gamma_8.data(), beta_8.data(),
        mean_8.data(), variance_8.data(),
        epsilon_8);

    // Activation, layer 9
    static std::array<Scalar, 4> layer_9_output;
    for (int i = 0; i < 4; ++i) {
        leakyrelu(layer_9_output[i], layer_8_output[i], 0.3);
    }

    // Dense, layer 10
    static std::array<Scalar, 9216> layer_10_output;
    Dense<Scalar, 9216>(
        layer_10_output.data(), layer_9_output.data(),
        weights_10.data(), biases_10.data(),
        4, linear, 0.0);


//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\// 


    static std::array<Scalar, 9216> model_output;

    for (int i = 0; i < 9216; i++) { model_output[i] = (layer_10_output[i] * output_norm_std[i]) + output_min_mean[i]; }

    return model_output;

